    ('>Részletesen:</span>', '>In detail:</span>'),
    # tényezők
    ("const T = [['soil', 'Az altalaj', 'Milyen rétegek vannak, milyen mélyen kezdődik a teherbíró réteg?', [2, 6]], ['water', 'A talajvíz-viszonyok', 'Milyen mélyen van, mennyit ingadozik, és mennyire agresszív a betonra?', [2, 4]],",
     "const T = [['soil', 'The ground', 'What layers are there, and how deep does the bearing stratum start?', [2, 6]], ['water', 'Groundwater conditions', 'How deep is it, how much does it fluctuate, and how aggressive is it to concrete?', [2, 4]],"),
    ("['sens', 'Az építmény szerkezete', 'Mennyire érzékeny a süllyedésre, mennyi süllyedéskülönbséget visel el károsodás nélkül?', [5]], ['load', 'A terhelési viszonyok', 'Mekkora, milyen irányú és mennyire külpontos a teher?', [3, 4]],",
     "['sens', 'The structure', 'How sensitive is it to settlement, and how much differential settlement can it take without damage?', [5]], ['load', 'The loading', 'How large is the load, in which direction does it act, and how eccentric is it?', [3, 4]],"),
    ("['nb', 'A szomszédos építmények', 'Milyen közel vannak, hány szintesek, milyen a szerkezetük – és min állnak?', [7, 9]], ['site', 'A kivitelezés körülményei', 'Mennyi a rendelkezésre álló hely, befér-e a gép, kiemelhető-e a munkagödör?', [8, 9]]];",
     "['nb', 'Neighbouring structures', 'How close are they, how many storeys do they have, what is their structure – and what do they stand on?', [7, 9]], ['site', 'Construction conditions', 'How much space is available, will the rig fit, can the excavation be dug?', [8, 9]]];"),
    # határállapotok
    ("const G = [['Teherbírási határállapotok', 'Biztonság a tönkremenetel ellen', [['brk', 'talajtörés', 3], ['sl', 'elcsúszás', 4], ['ov', 'felborulás (billenés)', 4], ['up', 'felúszás', 4], ['gl', 'általános állékonyság', 4]]],",
     "const G = [['Ultimate limit states', 'Safety against failure', [['brk', 'bearing failure', 3], ['sl', 'sliding', 4], ['ov', 'overturning (toppling)', 4], ['up', 'uplift', 4], ['gl', 'overall stability', 4]]],"),
    ("['Használhatósági határállapotok', 'Az épület használható marad', [['st', 'káros süllyedések', 5], ['df', 'süllyedéskülönbségek', 5]]],",
     "['Serviceability limit states', 'The building remains usable', [['st', 'harmful settlement', 5], ['df', 'differential settlements', 5]]],"),
    ("['Szerkezeti szilárdság', 'Maga az alap se menjen tönkre', [['str', 'az alapozási rendszer megfelelő szilárdsága', 3]]]];",
     "['Structural strength', 'The foundation itself must not fail either', [['str', 'adequate strength of the foundation system', 3]]]];"),
    ('<span>→ ${st}. állomás · ', '<span>→ station ${st} · '),
    # Pisa
    ("['1173', 'alapozás', 0.0, 'Augusztusban lerakják az alapokat. A torony mindössze kb. 3 m mély, kör alakú síkalapon áll – puha, egyenlőtlen vastagságú agyagrétegek fölött.', 1],",
     "['1173', 'foundations', 0.0, 'In August the foundations are laid. The tower stands on a circular shallow foundation only about 3 m deep – above soft clay layers of uneven thickness.', 1],"),
    ("['1178', '2. emelet', 0.25, 'A második emelet elkészülte után a torony süllyedni kezd, és megjelenik a dőlés. Az építés közel száz évre leáll – a szünetben a talaj konszolidálódik, és ez valószínűleg megmentette a tornyot.', 3],",
     "['1178', '2nd storey', 0.25, 'Once the second storey is complete, the tower starts to settle and the tilt appears. Construction stops for almost a hundred years – during the pause the soil consolidates, which probably saved the tower.', 3],"),
    ("['1372', 'kész', 1.6, 'Elkészül a harangház. A dőlés az építés alatt végig nőtt; a felső emeleteket az építők már a dőlés ellensúlyozására építették, ezért a torony ma kissé ívelt.', 8],",
     "['1372', 'complete', 1.6, 'The bell chamber is completed. The tilt kept growing throughout construction; the builders shaped the upper storeys to counteract it, which is why the tower is slightly curved today.', 8],"),
    ("['1990', '5,5°', 5.5, 'A dőlés eléri az 5,5°-ot. A tornyot lezárják a látogatók elől, és nemzetközi szakértői bizottság kezdi meg a stabilizálást.', 8],",
     "['1990', '5.5°', 5.5, 'The tilt reaches 5.5°. The tower is closed to visitors, and an international committee of experts starts to stabilise it.', 8],"),
    ("['2001', '−45 cm', 4.0, 'Ideiglenes ólom ellensúlyok az északi oldalon, majd óvatos talajkiemelés az alap északi széle alól: a dőlés kb. 45 cm-rel csökken.', 8],",
     "['2001', '−45 cm', 4.0, 'Temporary lead counterweights on the north side, then careful soil extraction from beneath the north edge of the foundation: the lean is reduced by about 45 cm.', 8],"),
    ("['ma', '3,97°', 3.97, 'A dőlés kb. 3,97°, a csúcs kb. 3,9 m-re tér el a függőlegestől – és a torony stabil.', 8]];",
     "['today', '3.97°', 3.97, 'The tilt is about 3.97°, the top is about 3.9 m off the vertical – and the tower is stable.', 8]];"),
    ("text: 'puha, egyenlőtlen agyagrétegek'", "text: 'soft clay layers of uneven thickness'"),
    ("(diff < 0.25 ? 'Telitalálat! ' : `A tipped ${fmt(diff, 1)} m-rel tért el. `) + 'Nem a süllyedés nagysága volt a baj, hanem az egyenlőtlensége: a torony egyenlőtlen vastagságú, puha agyagrétegeken áll, és a konszolidáció évszázadokig tartott. Ezért kell részletes talajvizsgálat.'",
     "(diff < 0.25 ? 'Spot on! ' : `Your guess was ${fmt(diff, 1)} m out. `) + 'The problem was not the amount of settlement but its unevenness: the tower stands on soft clay layers of uneven thickness, and consolidation went on for centuries. That is why a thorough ground investigation is needed.'"),
    ("'Állítsd be a tipped a csúszkával, majd kattints a gombra – vagy lapozz az évszámok között.'", "'Set your guess with the slider, then click the button – or browse through the years.'"),
    # villámkör
    ("const Q = [['Családi ház tömör homokon', 0, 'Kis teher, jó teherbírású talaj közvetlenül a felszín közelében: a sáv- vagy a lemezalap gazdaságos és biztonságos.'],",
     "const Q = [['A family house on dense sand', 0, 'Light load, good bearing ground right near the surface: a strip or raft foundation is economical and safe.'],"),
    ("['Egyemeletes ház puha szerves agyagon', 1, 'A szerves talaj nagyon összenyomható, és a süllyedése évekig tart: a terhet a teherbíró rétegig kell levinni – vagy előbb a talajt kell megjavítani.'],",
     "['A two-storey house on soft organic clay', 1, 'Organic soil is highly compressible and its settlement goes on for years: the load has to be taken down to the bearing stratum – or the ground has to be improved first.'],"),
    ("['Hídpillér a folyóban', 1, 'A víz kimoshatja a meder anyagát a pillér körül, és nagy a vízszintes erő is: a pillért a kimosási mélység alá, mélyre kell alapozni.'],",
     "['A bridge pier in a river', 1, 'Water can scour the riverbed around the pier, and the horizontal force is large too: the pier has to be founded deep, below the scour depth.'],"),
    ("['Toronyház két pinceszinttel, a teherbíró réteg 15 m mélyen', 1, 'Nagy teher, mély pince, mély teherbíró réteg: résfalas munkagödör és cölöpök – esetleg cölöppel gyámolított lemezalap.']];",
     "['A tower block with two basement levels, bearing stratum 15 m down', 1, 'Heavy load, deep basement, deep bearing stratum: a diaphragm-walled excavation and piles – or possibly a piled raft.']];"),
